query NationalNews($ntlOffset: Int!, $ntlLimit: Int!, $vOffset: Int!, $vLimit: Int!, $indOffset: Int!, $indLimit: Int!, $slug: String, $all: Boolean!) {
  viewer @include(if: $all) {
    id
    ... on Member {
      leagues {
        ...viewerNtlLeagueNewsFrag
        __typename
      }
      __typename
    }
    ... on ExternalStaff {
      leagues {
        ...viewerNtlLeagueNewsFrag
        __typename
      }
      __typename
    }
    __typename
  }
  national: league(id: 589) @include(if: $all) {
    id
    name
    slug
    news(offset: $ntlOffset, limit: $ntlLimit) {
      ...ntlNewsFrag
      __typename
    }
    __typename
  }
  indLeague: league(slug: $slug) @skip(if: $all) {
    id
    news(limit: $indLimit, offset: $indOffset) {
      ...ntlNewsFrag
      __typename
    }
    __typename
  }
}

fragment ntlNewsFrag on News {
  id
  title
  body
  featuredImage
  createdDate
  updatedDate
  effectiveDate
  isSticky
  league {
    id
    slug
    __typename
  }
  __typename
}

fragment viewerNtlLeagueNewsFrag on League {
  id
  slug
  news(offset: $vOffset, limit: $vLimit) {
    ...ntlNewsFrag
    __typename
  }
  __typename
}
